    title: "Cómo validar un archivo IFC antes de enviarlo (gratis, sin subirlo)",
    excerpt: "Tu BEP dice «entrega un IFC de calidad», pero nunca define cómo comprobarlo. Aquí tienes las tres formas reales de validar un archivo IFC (el servicio de buildingSMART, IfcOpenShell y una comprobación de salud en el navegador), qué detecta realmente cada una, y la checklist previa al envío que evita que los modelos se rechacen en el CDE.",
