        type: "p",
        text: "Si un elemento está en un nivel de Revit que no está marcado como Building Story, el exportador lo empuja hacia abajo, hasta la siguiente planta inferior, y por eso aparecen cosas en plantas inesperadas. Revit solo trata como plantas reales de la jerarquía espacial IFC los niveles marcados como Building Story.",
