        text: "Los problemas de coordenadas son de los fallos de IFC más desorientadores: la geometría es perfecta, pero el modelo está en el sitio equivocado -lejos del origen, desplazado respecto a las demás disciplinas, o directamente sin su posición real en el mundo. La causa raíz es que Revit tiene tres orígenes distintos y IFC tiene sus propias entidades de georreferenciación, y nada las relaciona entre sí a menos que tú lo hagas.",
