        text: "Por eso la misma conversación ocurre dos veces. La primera, alguien comprueba el modelo y lo da por aceptable. La segunda —un mes después, otra persona, otro hito— alguien lo vuelve a comprobar, porque no había ningún registro de la primera comprobación en el que nadie pudiera confiar.",
