          "Integridad de la jerarquía espacial: el esquema IFC exige IfcProject → IfcSite → IfcBuilding → IfcBuildingStorey. Los nodos ausentes (un Building directamente bajo Project, elementos físicos alojados en IfcSite) son infracciones del esquema con consecuencias reales más adelante.",
