        type: "p",
        text: "La validez de esquema es el suelo, no el techo. Un archivo en el que todos los elementos tienen Name=«» y cero conjuntos de propiedades cumple el esquema perfectamente. Un modelo sin IfcElementQuantity, sin clasificación y con todos los elementos físicos colocados directamente en IfcSite en lugar de en una planta también cumple el esquema perfectamente. Superar el comprobador de buildingSMART significa que el archivo STEP tiene el formato correcto; no dice nada sobre si los datos son útiles.",
