        text: "Los visores IFC son permisivos por diseño: están construidos para mostrar la geometría con independencia de la calidad de los datos. Un visor que se negara a abrir archivos inválidos según el esquema o pobres en datos sería inutilizable. Que la geometría se represente correctamente no dice nada sobre si los conjuntos de propiedades están completos, sobre las convenciones de nomenclatura, la estabilidad de los GUID, la clasificación ni ninguna de las 44 dimensiones de calidad. Visualizar un archivo es categóricamente distinto de validarlo.",
