        type: "p",
        text: "Un reflejo habitual es abrir el IFC, inspeccionar el modelo 3D y, si el edificio tiene buena pinta, dar el archivo por terminado. La geometría representa aproximadamente el 30 % de lo que hace útil a un archivo IFC. Los conjuntos de propiedades, las clasificaciones, los nombres de elemento, las asignaciones de tipo y los conjuntos de cantidades son lo que realmente consumen los sistemas de FM, los gestores de costes y los registros de activos del CDE. Un archivo geométricamente correcto pero con los conjuntos de propiedades en blanco falla en la entrega.",
