        type: "p",
        text: "Tratar la validación como el último paso antes de subir al CDE significa corregir incidencias bajo presión y sin margen. Un modelo con 800 incidencias de validación descubiertas el día antes del plazo o se entrega con problemas conocidos, o incumple el plazo. La cadencia correcta: Nivel 1 después de cada exportación, Nivel 2 antes de cada revisión interna (semanal como mínimo), Nivel 3 dos semanas antes de cada hito formal.",
