          "Antes de cada revisión interna (semanal o por sprint): ejecuta una comprobación completa de calidad de Nivel 2. Revisa la tendencia del Health Score. Una puntuación que baja entre revisiones significa que se están introduciendo incidencias nuevas: encuentra el origen antes de que se convierta en un patrón.",
