        q: "¿Qué es un IFC Health Score?",
        a: "Un IFC Health Score es un número de 0 a 100 que resume la calidad estructural y de datos de un modelo IFC frente a un conjunto de reglas de validación. No es un porcentaje de reglas superadas: es un modelo de penalización ponderado y logarítmico, en el que los errores estructurales pesan más que los avisos de datos. Una puntuación de 80 o más suele considerarse apta para la entrega al CDE; por debajo de 60 indica problemas estructurales que provocarán fallos en herramientas posteriores.",
