        q: "¿Cómo se calcula un IFC Health Score?",
        a: "La puntuación empieza en 100. Cada incumplimiento de una regla de validación resta puntos mediante una función de decaimiento logarítmico: las primeras incidencias restan más que las siguientes de esa misma regla. Los errores de esquema (fallos estructurales como un IfcProject ausente o una jerarquía rota) tienen un peso de penalización tres veces mayor que los avisos de datos (como incoherencias en el nombrado). La escala logarítmica evita que un modelo grande obtenga peor puntuación que uno pequeño con la misma densidad de problemas.",
