        text: "Si los resultados difieren, la causa más habitual es que se están aplicando conjuntos de reglas distintos. La validación en el navegador (44 reglas de calidad) y la validación de esquema en la nube (cumplimiento de ISO 10303-21) comprueban cosas distintas, no las mismas reglas en sitios distintos. Consulta la guía de niveles de validación para la distinción entre la comprobación de esquema de nivel 1, la comprobación de calidad de nivel 2 y el nivel 3 de IDS. Un resultado de IDS debería ser idéntico entre dos motores conformes a la especificación que ejecuten el mismo archivo .ids sobre el mismo modelo.",
