        text: "Nota de privacidad: al subir un archivo a Autodesk Viewer, este se almacena en los servidores de Autodesk. Para proyectos gubernamentales, instalaciones sanitarias, activos de defensa o cualquier modelo sujeto a requisitos de soberanía de datos, revisa el DPA de Autodesk y las opciones de residencia de datos antes de usar el visor gratuito.",
