            "Las capacidades completas de proyecto requieren una suscripción de pago",
            "Residencia de datos y RGPD: verifica los términos del DPA antes de usarlo en proyectos del sector público de la UE",
            "El rendimiento con modelos federados muy grandes depende de la carga del servidor",
