        text: "La versión gratuita de BIMcollab Zoom está limitada a un solo modelo y a un número limitado de incidencias BCF. La funcionalidad completa (federación de varios modelos, incidencias ilimitadas, sincronización en la nube en tiempo real) requiere una suscripción a BIMcollab Cloud. Para equipos que ya usan BIMcollab Cloud para la gestión de incidencias, Zoom es el complemento natural. Para equipos fuera del ecosistema de BIMcollab, Trimble Connect o IFC Viewer Online (con exportación a BCF) son probablemente mejores alternativas gratuitas.",
