        text: "Un informe regla por regla es esencial para corregir incidencias, pero resulta poco práctico como punto de control de entrega. El Health Score condensa las 44 reglas en un único número de 0 a 100 mediante penalizaciones logarítmicas ponderadas por gravedad: los errores (incidencias bloqueantes) tienen un peso 3 veces mayor que los avisos. Esto significa que un modelo con dos errores graves obtiene una puntuación significativamente más baja que uno con decenas de avisos menores.",
